fn valid_phone(phone: String) -> Bool {
  let chars = split(phone, "")
  let digits = match first(chars) {
    Some("+") => drop(chars, 1),
    _ => chars,
  }
  if len(digits) < 7 || len(digits) > 15 {
    return false
  }
  for digit in digits {
    if digit < "0" || digit > "9" {
