"""Recording and summarizing product star ratings."""

import sqlite3

from fastapi import APIRouter

from .catalog import find_product
from .db import transaction
from .errors import ApiError
from .schemas import NewRating, RatingSummary

router = APIRouter()


def rating_summary(conn: sqlite3.Connection, sku: str) -> RatingSummary:
    row = conn.execute(
        "SELECT COUNT(*) AS count, AVG(stars) AS average FROM product_ratings WHERE sku = ?",
        (sku,),
    ).fetchone()
    return RatingSummary(sku=sku, count=row["count"], average=row["average"])


@router.post("/products/{sku:path}/ratings")
def rate_product(sku: str, body: NewRating) -> RatingSummary:
    with transaction() as conn:
        if find_product(conn, sku) is None:
            raise ApiError("Missing", sku=sku)
        conn.execute(
            "INSERT INTO product_ratings (sku, stars) VALUES (?, ?)", (sku, body.stars)
        )
        return rating_summary(conn, sku)


@router.get("/products/{sku:path}/rating")
def get_product_rating(sku: str) -> RatingSummary:
    with transaction() as conn:
        if find_product(conn, sku) is None:
            raise ApiError("Missing", sku=sku)
        return rating_summary(conn, sku)
