"""Discount codes: registration and lookup."""

import sqlite3

from fastapi import APIRouter

from .db import transaction
from .errors import ApiError
from .schemas import Discount

router = APIRouter()


def find_discount(conn: sqlite3.Connection, code: str) -> Discount | None:
    row = conn.execute(
        "SELECT percent FROM discounts WHERE code = ?", (code,)
    ).fetchone()
    return Discount(code=code, percent=row["percent"]) if row is not None else None


@router.post("/discounts")
def add_discount(discount: Discount) -> Discount:
    with transaction() as conn:
        inserted = conn.execute(
            "INSERT INTO discounts (code, percent) VALUES (?, ?) "
            "ON CONFLICT (code) DO NOTHING",
            (discount.code, discount.percent),
        )
        if inserted.rowcount == 0:
            raise ApiError("Invalid", reason=f"duplicate code {discount.code}")
    return discount
