  route: POST "/orders/{id}/discount"
  effects: store(discounts), store(orders)
{
  let order = try discountable_order(id)
  return match get(discounts, input.code) {
    Some(d) => Ok(save(orders, discounted(order, d.percent))),
    None => Err(UnknownCode(input.code)),
  }
