  let tail = order.total % 100 * percent
  let adjustment = match tail % 100 < 0 {
    true => 1,
    false => 0,
  }
  let reduction = order.total / 100 * percent + tail / 100 - adjustment
  var updated = order
  updated.total = updated.total - reduction
  return updated
}

