type User {
  email: String,
  name: String,
  password_hash: String,
  id: String,
}

type Signup {
  email: String,
  name: String,
  password: String,
}

type Profile {
  email: String,
  name: String,
}

type UserError =
  | Taken(email: String)
  | BadLogin

api fn signup(input: Signup) -> Result[Profile, UserError]
  route: POST "/users"
  effects: rand, store(users)
  requires: is_email(input.email) && str_len(trim(input.name)) > 0 && str_len(input.password) >= 8
{
  if is_some(get(users, input.email)) {
    return Err(Taken(input.email))
  }
  let user = User {
    email: input.email,
    name: trim(input.name),
    password_hash: hash_password(input.password),
    id: uuid(),
  }
  insert(users, user)
  return Ok(profile(user))
}

fn profile(u: User) -> Profile {
  return Profile { email: u.email, name: u.name }
}

api fn list_users(page: Int, per_page: Int) -> List[Profile]
  route: GET "/users"
  effects: store(users)
  requires: page >= 1 && per_page >= 1 && per_page <= 25
{
  let all = scan(users)
  let preceding_pages = page - 1
  if preceding_pages > len(all) / per_page {
    return []
  }
  let sorted = sort_by(all, |u| u.email)
  return sorted
    |> drop(preceding_pages * per_page)
    |> take(per_page)
    |> map(profile)
}

api fn login(input: Signup) -> Result[Profile, UserError]
  route: POST "/login"
  effects: store(users)
{
  return match get(users, input.email) {
    Some(u) => match verify_password(input.password, u.password_hash) {
      true => Ok(profile(u)),
      false => Err(BadLogin),
    },
    None => Err(BadLogin),
  }
}

