export interface Restock {
  amount: number;
}

export interface Signup {
  email: string;
  name: string;
  password: string;
}

export interface Profile {
  email: string;
  name: string;
}

export interface Line {
  sku: string;
  quantity: number;
}

export type Status = { kind: "Open" } | { kind: "Paid"; receipt: string } | { kind: "Cancelled" };

export interface Order {
  id: number;
  email: string;
  lines: Line[];
  total: number;
  status: Status;
}

export interface NewOrder {
  email: string;
  lines: Line[];
}

export interface Summary {
  email: string;
  orders: number;
  spent: number;
}

/** Errors sent by the API or reported by the fetch client. */
