  | { readonly kind: "BadQuantity"; sku: string; quantity: number }
  | { readonly kind: "Missing"; sku: string }
  | { readonly kind: "Invalid"; reason: string }
  | { readonly kind: "Taken"; email: string }
  | { readonly kind: "BadLogin" }
  | { readonly kind: "ValidationError"; rule: string }
  | { readonly kind: "InternalError" }
  | { readonly kind: "TransportError"; status?: number; message?: string };
